import{U as e,W as t,nt as n,t as r}from"./chunks/framework.CPHJXLir.js";var i=JSON.parse(`{"title":"Installing Business Central Locally","description":"","frontmatter":{},"headers":[],"relativePath":"installation-and-setup/index.md","filePath":"installation-and-setup/index.md"}`),a={name:`installation-and-setup/index.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="installing-business-central-locally" tabindex="-1">Installing Business Central Locally <a class="header-anchor" href="#installing-business-central-locally" aria-label="Permalink to “Installing Business Central Locally”">​</a></h1><p>Before we start building extensions and writing AL code, we need a working <strong>Microsoft Dynamics 365 Business Central development environment</strong>.</p><p>A development environment allows us to connect to Business Central, write AL code, compile extensions, test our changes, and debug our applications.</p><p>There are several ways to set up this environment. The two main approaches we&#39;ll consider are running Business Central locally and using an online sandbox.</p><h2 id="_1-option-a-install-business-central-locally" tabindex="-1">1. Option A: Install Business Central Locally <a class="header-anchor" href="#_1-option-a-install-business-central-locally" aria-label="Permalink to “1. Option A: Install Business Central Locally”">​</a></h2><p>Running Business Central locally allows us to host an instance of Business Central on our own computer. This gives us a dedicated environment for development and experimentation without modifying a production system.</p><p>There are two main approaches to consider.</p><h3 id="a-using-docker-containers" tabindex="-1">A. Using Docker Containers <a class="header-anchor" href="#a-using-docker-containers" aria-label="Permalink to “A. Using Docker Containers”">​</a></h3><p>Docker allows us to run Business Central inside a container rather than installing the entire application directly on Windows.</p><p>A <strong>container</strong> is an isolated environment that packages an application and the components it needs to run.</p><p>Microsoft provides Business Central artifacts that can be used to create container-based development environments. The <code>BCContainerHelper</code> PowerShell module simplifies the process of creating and managing these containers.</p><p><strong>Advantages:</strong></p><ul><li>Makes it easier to create and recreate development environments.</li><li>Allows us to work with different Business Central versions.</li><li>Keeps the development environment separate from the host operating system.</li><li>Supports testing extensions in a controlled environment.</li></ul><p><strong>Important considerations:</strong></p><ul><li>Business Central containers require Windows containers, not the default Linux containers used by Docker.</li><li>Docker must be configured correctly, and the Windows edition and container host must meet the relevant requirements.</li><li>Containers consume system resources, so available RAM and disk space matter.</li></ul><p><strong>Recommended resource:</strong> <a href="https://learn.microsoft.com/en-us/dynamics365/business-central/dev-itpro/developer/devenv-running-container-development" target="_blank" rel="noreferrer">Running a Container-Based Development Environment</a></p><h3 id="b-using-the-business-central-installation-media" tabindex="-1">B. Using the Business Central Installation Media <a class="header-anchor" href="#b-using-the-business-central-installation-media" aria-label="Permalink to “B. Using the Business Central Installation Media”">​</a></h3><p>Another option is to install an on-premises version of Business Central using Microsoft&#39;s installation media.</p><p>The installation media contains the components required to install and configure an on-premises Business Central environment. Depending on the selected components, this can include the Business Central Server, web client, and database-related components.</p><p>This approach is useful when you want to understand the architecture of an on-premises deployment or need access to components that aren&#39;t available in an online sandbox.</p><p><strong>Advantages:</strong></p><ul><li>Provides an on-premises Business Central environment.</li><li>Gives you more control over the installed server components and configuration.</li><li>Can be useful when learning about Business Central Server and SQL Server integration.</li></ul><p><strong>Important considerations:</strong></p><ul><li>Installation and configuration can involve more manual work.</li><li>You must ensure that the Business Central version is compatible with your operating system and other dependencies.</li><li>Some configurations require Microsoft SQL Server and additional setup.</li></ul><p>For someone primarily learning AL development, a container-based environment is often a convenient starting point if the machine supports it.</p><h2 id="_2-option-b-use-business-central-online" tabindex="-1">2. Option B: Use Business Central Online <a class="header-anchor" href="#_2-option-b-use-business-central-online" aria-label="Permalink to “2. Option B: Use Business Central Online”">​</a></h2><p>If running Business Central locally isn&#39;t practical, you can use a <strong>Business Central online sandbox</strong>.</p><p>A sandbox is an isolated environment used for development, testing, and experimentation without making changes directly to a production environment.</p><p>Microsoft hosts the online environment, so you don&#39;t need to install and maintain the Business Central Server on your computer.</p><p>You can use Visual Studio Code and the AL Language extension to connect to the sandbox, download the required symbols, develop extensions, and publish your changes.</p><p><strong>Advantages:</strong></p><ul><li>No need to host Business Central locally.</li><li>Microsoft manages the underlying infrastructure.</li><li>Provides a convenient environment for learning AL development.</li><li>Allows you to develop and test extensions using Visual Studio Code.</li></ul><p><strong>Important considerations:</strong></p><ul><li>Access depends on having an eligible Business Central environment and the necessary permissions.</li><li>Some capabilities available in locally hosted containers aren&#39;t available in online sandboxes.</li><li>Online environments are managed by Microsoft, so you have less control over the underlying server and database.</li><li>Sandbox environments can be updated or relocated, which can affect extensions published directly to them.</li></ul><p><strong>Recommended resource:</strong> <a href="https://learn.microsoft.com/en-us/dynamics365/business-central/dev-itpro/developer/devenv-sandbox-overview" target="_blank" rel="noreferrer">Sandbox Environments for Business Central Development</a></p><h3 id="do-i-need-a-business-email-address" tabindex="-1">Do I need a business email address? <a class="header-anchor" href="#do-i-need-a-business-email-address" aria-label="Permalink to “Do I need a business email address?”">​</a></h3><p>You may need an eligible work or school account, an appropriate Microsoft Entra ID tenant, and a Business Central subscription or trial to access an online environment.</p><p>A custom-domain business email address is not, by itself, a universal requirement for every development setup. However, account eligibility and trial availability can vary.</p><p>Before purchasing a domain or email-hosting service, check Microsoft&#39;s current requirements and available trial options.</p><h2 id="further-reading-and-official-documentation" tabindex="-1">Further Reading and Official Documentation <a class="header-anchor" href="#further-reading-and-official-documentation" aria-label="Permalink to “Further Reading and Official Documentation”">​</a></h2><p>Use the following resources to deepen your understanding and troubleshoot setup issues.</p><table tabindex="0"><thead><tr><th>Resource</th><th>What You&#39;ll Learn</th></tr></thead><tbody><tr><td><a href="https://learn.microsoft.com/en-us/dynamics365/business-central/dev-itpro/developer/" target="_blank" rel="noreferrer">Business Central Developer Documentation</a></td><td>The official technical documentation for Business Central development.</td></tr><tr><td><a href="https://learn.microsoft.com/en-us/dynamics365/business-central/dev-itpro/developer/devenv-get-started" target="_blank" rel="noreferrer">Get Started with AL</a></td><td>How to prepare your development environment and begin writing AL code.</td></tr><tr><td><a href="https://learn.microsoft.com/en-us/dynamics365/business-central/dev-itpro/developer/devenv-running-container-development" target="_blank" rel="noreferrer">Container-Based Development Environment</a></td><td>How to configure Docker and create a local Business Central container.</td></tr><tr><td><a href="https://learn.microsoft.com/en-us/dynamics365/business-central/dev-itpro/developer/devenv-sandbox-overview" target="_blank" rel="noreferrer">Sandbox Environments</a></td><td>The differences between online and container-based sandboxes.</td></tr><tr><td><a href="https://learn.microsoft.com/en-us/dynamics365/business-central/dev-itpro/developer/devenv-dev-overview" target="_blank" rel="noreferrer">Developing Extensions in AL</a></td><td>An introduction to extension development and Business Central application objects.</td></tr><tr><td><a href="https://learn.microsoft.com/en-us/dynamics365/business-central/dev-itpro/developer/devenv-al-extension-configuration" target="_blank" rel="noreferrer">AL Language Extension Configuration</a></td><td>How to configure the AL development tools in Visual Studio Code.</td></tr><tr><td><a href="https://learn.microsoft.com/en-us/dynamics365/business-central/dev-itpro/developer/devenv-dev-faq" target="_blank" rel="noreferrer">Business Central Development FAQ</a></td><td>Answers to common questions and troubleshooting guidance.</td></tr><tr><td><a href="https://learn.microsoft.com/en-us/dynamics365/business-central/dev-itpro/developer/devenv-code-spaces-al" target="_blank" rel="noreferrer">GitHub Codespaces for AL Development</a></td><td>How to use a cloud-hosted development environment for AL development.</td></tr></tbody></table>`,42)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};